// Original vector scenes: different compositions for school, office, wedding, birth and late life.
export function illustration(item){const type=item.type,text=item.text||'';let scene='',label='人生新章';
const person=(x,y,color='#52796b',small=false)=>`<g transform="translate(${x} ${y}) scale(${small?.7:1})"><circle cy="-32" r="13" fill="#e6bd9b"/><path d="M-14-36Q-12-58 13-38L8-43-8-41Z" fill="#384c43"/><path d="M-19 11V-8Q-18-24 0-22Q18-24 19-8V11" fill="${color}"/><path d="M-9 11V34M9 11V34" stroke="#41574b" stroke-width="9" stroke-linecap="round"/></g>`;
if(['grade','school','graduation'].includes(type)){label=text.includes('幼儿园')?'童年的校园':text.includes('大学')||text.includes('研究')?'求知与毕业':'校园新学年';scene=`<rect x="65" y="59" width="290" height="112" rx="5" fill="#e8dfc9"/><path d="M45 62L210 14 375 62Z" fill="#507b6a"/><path d="M190 172V103H230V172" fill="#658974"/><g fill="#fff9e6">${[86,135,250,299].map(x=>`<rect x="${x}" y="85" width="30" height="28"/><rect x="${x}" y="126" width="30" height="25"/>`).join('')}</g><circle cx="210" cy="56" r="15" fill="#f5e9c9"/><path d="M210 45V56L219 60" fill="none" stroke="#ab8548" stroke-width="2"/>${person(146,169,'#a28a66',true)}${person(275,169,'#5b8b80',true)}${type==='graduation'?'<path d="M166 57L210 40 254 57 210 75Z" fill="#253f35"/><path d="M245 60V91" stroke="#c4a053" stroke-width="3"/>':''}`;}
else if(type==='promotion'||type==='contact'){label='任职与公共服务';scene=`<path d="M50 66L210 19 370 66Z" fill="#537766"/><rect x="65" y="69" width="290" height="98" fill="#e8dfc9"/>${[84,143,202,261,320].map(x=>`<rect x="${x}" y="75" width="17" height="84" fill="#faf4df"/>`).join('')}<path d="M45 171H375M35 182H385" stroke="#a4b39c" stroke-width="9"/>${person(209,139)}<path d="M171 162H251V171H171Z" fill="#b9945a"/><circle cx="330" cy="38" r="17" fill="#c4a053"/><path d="M324 39L329 44 339 32" fill="none" stroke="#fff7df" stroke-width="3"/>`;}
else if(type==='marriage'||type==='descendant-marriage'){label='携手成家';scene=`<path d="M109 169V66Q210-16 311 66V169" stroke="#a58a62" stroke-width="8" fill="none"/><path d="M109 66Q210 5 311 66" stroke="#64866c" stroke-width="17" fill="none"/>${person(175,139,'#6c8c7a')}${person(245,139,'#b68c84')}<path d="M193 135Q210 151 227 135" stroke="#d6b290" stroke-width="9" fill="none"/><path d="M210 75C176 50 190 35 210 48C230 35 244 50 210 75" fill="#b98a74"/>`;}
else if(type==='birth'){label='新生命，新的牵挂';scene=`<path d="M131 139Q210 208 290 139" fill="#b59872"/><path d="M135 124Q210 154 285 124V143H135Z" fill="#ddd0ac"/><path d="M132 128Q129 35 210 40V128Z" fill="#b7c5a5"/><ellipse cx="222" cy="122" rx="51" ry="24" fill="#f7eed6"/><circle cx="243" cy="112" r="19" fill="#e6bd9b"/><path d="M235 113L239 115M248 115L252 112" stroke="#5a6554" stroke-width="2"/><path d="M145 155L126 183M275 155L293 183" stroke="#987c55" stroke-width="7"/><path d="M79 55L83 67 96 68 85 76 88 89 77 81 67 88 69 75 59 67 73 66Z" fill="#c1a45f"/>`;}
else if(type==='illness'||type==='recovery'){label=type==='recovery'?'康复与陪伴':'照护与休养';scene=`<rect x="76" y="42" width="270" height="127" rx="9" fill="#e3e9da"/><path d="M101 124H319V160H101Z" fill="#9eb4a0"/><path d="M100 160V185M317 160V185" stroke="#728b7b" stroke-width="8"/><ellipse cx="184" cy="117" rx="60" ry="23" fill="#f8f1dc"/><circle cx="124" cy="110" r="17" fill="#e3b997"/><path d="M282 65V99M265 82H299" stroke="#a98d73" stroke-width="8"/>${person(353,139,'#90aaa0',true)}`;}
else if(type==='bereavement'){label='珍藏共同的时光';scene='<path d="M155 177H265L248 161H172Z" fill="#b8ad94"/><rect x="192" y="84" width="37" height="78" rx="3" fill="#f5e7b9"/><path d="M210 80C187 62 205 48 211 34C230 57 232 68 210 80" fill="#ba9b56"/><path d="M102 164Q105 95 151 73M318 164Q315 95 269 73" stroke="#92a083" stroke-width="4" fill="none"/>';}
else{label=type==='divorce'?'各自前行，仍有牵挂':'岁月与家人';scene=`<circle cx="308" cy="61" r="32" fill="#c2cba7"/><path d="M307 84V171" stroke="#9f9474" stroke-width="9"/><path d="M96 148H274M110 161V183M258 161V183" stroke="#a9926e" stroke-width="7"/>${person(167,117,'#78917b',true)}${person(229,117,'#b19b86',true)}`;}
return `<svg class="event-illustration" viewBox="0 0 420 210" role="img" aria-label="${label}"><rect width="420" height="210" rx="12" fill="#f0ecde"/><circle cx="65" cy="36" r="21" fill="#ddc99d" opacity=".6"/><path d="M0 186Q100 170 210 186T420 184V210H0Z" fill="#dce3d0"/>${scene}</svg>`;}
